import { useEffect, useRef } from 'react'
import useMagneticEffect from '../hooks/useMagneticEffect'
import './Hero.css'

export default function Hero() {
    const videoRef = useRef(null)
    const magneticBtnRef = useMagneticEffect(15)

    // Ensure video only plays when in viewport to save resources
    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (videoRef.current) {
                    if (entry.isIntersecting) {
                        // Video is in viewport, consider playing
                        // For Sketchfab iframes, autoplay is usually handled by the src URL
                        // This useEffect might be more relevant for actual <video> tags
                    } else {
                        // Video is out of viewport, consider pausing
                    }
                }
            },
            { threshold: 0.5 } // Trigger when 50% of the video is visible
        )

        if (videoRef.current) {
            observer.observe(videoRef.current)
        }

        return () => {
            if (videoRef.current) {
                observer.unobserve(videoRef.current)
            }
        }
    }, [])

    return (
        <section className="hero">
            <div className="container hero-grid">
                <div className="hero-content">
                    <div className="mono-label" style={{ marginBottom: '1rem' }}>[SYS_INIT] 3D_MANUFACTURING</div>
                    <h1>
                        Precision-Crafted Dental Prosthetics.<br />
                        <span className="text-gradient-brand">Delivered in 48 Hours.</span>
                    </h1>
                    <p>
                        The intersection of medical precision and deep-tech manufacturing. We deploy nano-ceramic
                        resins and advanced CAD/CAM architecture to supply Vidarbha's leading dental clinics.
                    </p>
                    <p className="hero-tagline">"We carry a 4,600-year legacy into India's digital medical future."</p>
                    <div className="hero-cta-group" style={{ 
                        marginTop: '2rem', 
                        display: 'flex', 
                        gap: '1rem',
                        animation: 'fadeInUp 1s ease-out 1s both'
                    }}>
                        <a ref={magneticBtnRef} href="#products" className="btn btn-primary" style={{ padding: '1rem 2rem', fontSize: '1rem' }}>
                            Explore Products
                            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" style={{ marginLeft: '0.5rem' }}>
                                <line x1="5" y1="12" x2="19" y2="12"></line>
                                <polyline points="12 5 19 12 12 19"></polyline>
                            </svg>
                        </a>
                        <a href="#workflow" className="btn btn-outline" style={{ padding: '1rem 2rem', fontSize: '1rem' }}>
                            Our Workflow
                        </a>
                    </div>
                </div>

                <div className="hero-visual">
                    <div className="tech-pedestal" />
                    <div className="tooth-video-wrapper">
                        <div ref={videoRef} className="sketchfab-embed-wrapper" style={{ width: '100%', height: '100%', position: 'relative', zIndex: 2 }}>
                            <iframe
                                title="Crown Preparation"
                                frameBorder="0"
                                allowFullScreen
                                mozallowfullscreen="true"
                                webkitallowfullscreen="true"
                                allow="autoplay; fullscreen; xr-spatial-tracking"
                                xr-spatial-tracking="true"
                                execution-while-out-of-viewport="true"
                                execution-while-not-rendered="true"
                                web-share="true"
                                src="https://sketchfab.com/models/0439ccf0363b44bdaa9e2713b0a27011/embed?autospin=1&autostart=1&preload=1&transparent=1&ui_infos=0&ui_stop=0&ui_inspector=0&ui_watermark_link=0&ui_watermark=0&ui_hint=0&ui_theme=dark"
                                style={{ width: '100%', height: '400px', filter: 'drop-shadow(0 0 40px var(--accent-glow))' }}
                            >
                            </iframe>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    )
}
